    bytes32 public constant COMPLIANCE_OFFICER_ROLE = keccak256("COMPLIANCE_OFFICER_ROLE");
    
    IIdentityRegistry public immutable identityRegistry;
    
    mapping(address => bool) private _tokenBound;
    mapping(address => bool) private _blacklisted;
    mapping(bytes32 => address) private _complianceRules;
    
    uint256 public constant MAX_SHAREHOLDERS = 2000;
    mapping(address => uint256) private _shareholderCount;
    
    constructor(address _identityRegistry) {
        require(_identityRegistry != address(0), "Invalid identity registry");
        identityRegistry = IIdentityRegistry(_identityRegistry);
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(COMPLIANCE_OFFICER_ROLE, msg.sender);
    }
    
    function canTransfer(
        address from, 
        address to, 
        uint256 amount
    ) external view override returns (bool) {
        // Check blacklist
        if (_blacklisted[from] || _blacklisted[to]) {
            return false;
        }
        
        // For minting (from == address(0)), only check recipient
        if (from == address(0)) {
            return identityRegistry.isVerified(to);
        }
        
        // For burning (to == address(0)), allow if sender is verified
        if (to == address(0)) {
            return identityRegistry.isVerified(from);
        }
        
        // For transfers, both parties must be verified
        return identityRegistry.isVerified(from) && identityRegistry.isVerified(to);
    }
    
    function transferred(address from, address to, uint256 amount) external override {
        require(_tokenBound[msg.sender], "Token not bound to compliance");
        
        // Update shareholder count for minting
        if (from == address(0) && amount > 0) {
            _shareholderCount[msg.sender]++;
        }
        
        // Update shareholder count for burning
        if (to == address(0) && amount > 0) {
            if (_shareholderCount[msg.sender] > 0) {
                _shareholderCount[msg.sender]--;
            }
        }
        
        // Emit compliance interaction event if needed
        // emit ComplianceInteraction(from, to, amount);
    }
    
    function created(address to, uint256 amount) external override {
        require(_tokenBound[msg.sender], "Token not bound to compliance");
        // Handle token creation logic
    }
    
    function destroyed(address from, uint256 amount) external override {
        require(_tokenBound[msg.sender], "Token not bound to compliance");
        // Handle token destruction logic
    }
    
    function bindToken(address token) external override onlyRole(DEFAULT_ADMIN_ROLE) {
        require(token != address(0), "Invalid token address");
        _tokenBound[token] = true;
        emit TokenBound(token);
    }
    
    function unbindToken(address token) external override onlyRole(DEFAULT_ADMIN_ROLE) {
        _tokenBound[token] = false;
        emit TokenUnbound(token);
    }
    
    function isTokenBound(address token) external view override returns (bool) {
        return _tokenBound[token];
    }
    
    function addComplianceRule(
        bytes32 ruleType, 
        address ruleContract
    ) external override onlyRole(COMPLIANCE_OFFICER_ROLE) {
        require(ruleContract != address(0), "Invalid rule contract");
        _complianceRules[ruleType] = ruleContract;
        emit ComplianceRuleAdded(ruleType, ruleContract);
    }
    
    function removeComplianceRule(bytes32 ruleType) external override onlyRole(COMPLIANCE_OFFICER_ROLE) {
        delete _complianceRules[ruleType];
    }
    
    function getComplianceRule(bytes32 ruleType) external view override returns (address) {
        return _complianceRules[ruleType];
    }
    
    // Blacklist management
    function addToBlacklist(address _address) external onlyRole(COMPLIANCE_OFFICER_ROLE) {
        require(_address != address(0), "Invalid address");
        _blacklisted[_address] = true;
    }
    
    function removeFromBlacklist(address _address) external onlyRole(COMPLIANCE_OFFICER_ROLE) {
        _blacklisted[_address] = false;
    }
    
    function isBlacklisted(address _address) external view returns (bool) {
        return _blacklisted[_address];
    }
    
    // Utility functions
    function getShareholderCount(address token) external view returns (uint256) {
        return _shareholderCount[token];
    }
}

contracts/EscrowPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./LeaseAgreement.sol";

/**
 * @title EscrowPayment
 * @dev Handles escrow payments and automated rent collection
 */
contract EscrowPayment is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;
    
    bytes32 public constant ESCROW_AGENT_ROLE = keccak256("ESCROW_AGENT_ROLE");
    bytes32 public constant PAYMENT_PROCESSOR_ROLE = keccak256("PAYMENT_PROCESSOR_ROLE");
    
    enum EscrowStatus { PENDING, FUNDED, RELEASED, REFUNDED, DISPUTED }
    
    struct EscrowDeposit {
        uint256 escrowId;
        uint256 leaseId;
        address depositor;
        address beneficiary;
        address token;
        uint256 amount;
        EscrowStatus status;
        uint256 createdAt;
        uint256 releaseDate;
        string purpose;
    }
    
    struct RentPayment {
        uint256 leaseId;
        uint256 amount;
        address token;
        uint256 dueDate;
        uint256 paidDate;
        bool isPaid;
        address payer;
    }
    
    LeaseAgreement public immutable leaseAgreement;
    
    uint256 private _escrowCounter;
    uint256 private _paymentCounter;
    
    mapping(uint256 => EscrowDeposit) private _escrows;
    mapping(uint256 => RentPayment) private _rentPayments;
    mapping(uint256 => uint256[]) private _leasePayments; // leaseId => paymentIds
    
    // Events
    event EscrowCreated(
        uint256 indexed escrowId,
        uint256 indexed leaseId,
        address indexed depositor,
        uint256 amount
    );
    
    event EscrowFunded(uint256 indexed escrowId, uint256 amount);
    event EscrowReleased(uint256 indexed escrowId, address indexed to, uint256 amount);
    event EscrowRefunded(uint256 indexed escrowId, address indexed to, uint256 amount);
    
    event RentPaymentCreated(
        uint256 indexed paymentId,
        uint256 indexed leaseId,
        uint256 amount,
        uint256 dueDate
    );
    
    event RentPaid(
        uint256 indexed paymentId,
        uint256 indexed leaseId,
        address indexed payer,
        uint256 amount
    );
    
    constructor(address _leaseAgreement) {
        require(_leaseAgreement != address(0), "Invalid lease agreement");
        leaseAgreement = LeaseAgreement(_leaseAgreement);
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ESCROW_AGENT_ROLE, msg.sender);
        _grantRole(PAYMENT_PROCESSOR_ROLE, msg.sender);
    }
    
    // Escrow functions
    function createEscrow(
        uint256 leaseId,
        address beneficiary,
        address token,
        uint256 amount,
        uint256 releaseDate,
        string memory purpose
    ) external returns (uint256) {
        require(beneficiary != address(0), "Invalid beneficiary");
        require(token != address(0), "Invalid token");
        require(amount > 0, "Amount must be greater than 0");
        require(releaseDate > block.timestamp, "Release date must be in the future");
        
        // Verify lease exists
        LeaseAgreement.Lease memory lease = leaseAgreement.getLease(leaseId);
        require(lease.leaseId != 0, "Lease does not exist");
        
        _escrowCounter++;
        uint256 escrowId = _escrowCounter;
        
        _escrows[escrowId] = EscrowDeposit({
            escrowId: escrowId,
            leaseId: leaseId,
            depositor: msg.sender,
            beneficiary: beneficiary,
            token: token,
            amount: amount,
            status: EscrowStatus.PENDING,
            createdAt: block.timestamp,
            releaseDate: releaseDate,
            purpose: purpose
        });
        
        emit EscrowCreated(escrowId, leaseId, msg.sender, amount);
        return escrowId;
    }
    
    function fundEscrow(uint256 escrowId) external nonReentrant {
        EscrowDeposit storage escrow = _escrows[escrowId];
        require(escrow.escrowId != 0, "Escrow does not exist");
        require(escrow.status == EscrowStatus.PENDING, "Escrow already funded");
        require(msg.sender == escrow.depositor, "Only depositor can fund");
        
        IERC20(escrow.token).safeTransferFrom(msg.sender, address(this), escrow.amount);
        escrow.status = EscrowStatus.FUNDED;
        
        emit EscrowFunded(escrowId, escrow.amount);
    }
    
    function releaseEscrow(uint256 escrowId) external onlyRole(ESCROW_AGENT_ROLE) nonReentrant {
        EscrowDeposit storage escrow = _escrows[escrowId];
        require(escrow.escrowId != 0, "Escrow does not exist");
        require(escrow.status == EscrowStatus.FUNDED, "Escrow not funded");
        require(block.timestamp >= escrow.releaseDate, "Release date not reached");
        
        escrow.status = EscrowStatus.RELEASED;
        IERC20(escrow.token).safeTransfer(escrow.beneficiary, escrow.amount);
        
        emit EscrowReleased(escrowId, escrow.beneficiary, escrow.amount);
    }
    
    function refundEscrow(uint256 escrowId) external onlyRole(ESCROW_AGENT_ROLE) nonReentrant {
        EscrowDeposit storage escrow = _escrows[escrowId];
        require(escrow.escrowId != 0, "Escrow does not exist");
        require(escrow.status == EscrowStatus.FUNDED, "Escrow not funded");
        
        escrow.status = EscrowStatus.REFUNDED;
        IERC20(escrow.token).safeTransfer(escrow.depositor, escrow.amount);
        
        emit EscrowRefunded(escrowId, escrow.depositor, escrow.amount);
    }
    
    // Rent payment functions
    function createRentPayment(
        uint256 leaseId,
        uint256 amount,
        address token,
        uint256 dueDate
    ) external onlyRole(PAYMENT_PROCESSOR_ROLE) returns (uint256) {
        require(amount > 0, "Amount must be greater than 0");
        require(token != address(0), "Invalid token");
        require(dueDate > block.timestamp, "Due date must be in the future");
        
        // Verify lease exists and is active
        require(leaseAgreement.isLeaseActive(leaseId), "Lease is not active");
        
        _paymentCounter++;
        uint256 paymentId = _paymentCounter;
        
        _rentPayments[paymentId] = RentPayment({
            leaseId: leaseId,
            amount: amount,
            token: token,
            dueDate: dueDate,
            paidDate: 0,
            isPaid: false,
            payer: address(0)
        });
        
        _leasePayments[leaseId].push(paymentId);
        
        emit RentPaymentCreated(paymentId, leaseId, amount, dueDate);
        return paymentId;
    }
    
    function payRent(uint256 paymentId) external nonReentrant {
        RentPayment storage payment = _rentPayments[paymentId];
        require(payment.leaseId != 0, "Payment does not exist");
        require(!payment.isPaid, "Payment already made");
        require(block.timestamp <= payment.dueDate + 7 days, "Payment deadline passed");
        
        // Get lease details
        LeaseAgreement.Lease memory lease = leaseAgreement.getLease(payment.leaseId);
        require(msg.sender == lease.tenant, "Only tenant can pay rent");
        
        IERC20(payment.token).safeTransferFrom(msg.sender, lease.landlord, payment.amount);
        
        payment.isPaid = true;
        payment.paidDate = block.timestamp;
        payment.payer = msg.sender;
        
        emit RentPaid(paymentId, payment.leaseId, msg.sender, payment.amount);
    }
    
    // View functions
    function getEscrow(uint256 escrowId) external view returns (EscrowDeposit memory) {
        require(_escrows[escrowId].escrowId != 0, "Escrow does not exist");
        return _escrows[escrowId];
    }
    
    function getRentPayment(uint256 paymentId) external view returns (RentPayment memory) {
        require(_rentPayments[paymentId].leaseId != 0, "Payment does not exist");
        return _rentPayments[paymentId];
    }
    
    function getLeasePayments(uint256 leaseId) external view returns (uint256[] memory) {
        return _leasePayments[leaseId];
    }
    
    function getTotalEscrows() external view returns (uint256) {
        return _escrowCounter;
    }
    
    function getTotalPayments() external view returns (uint256) {
        return _paymentCounter;
    }
    
    function isPaymentDue(uint256 paymentId) external view returns (bool) {
        RentPayment memory payment = _rentPayments[paymentId];
        return !payment.isPaid && block.timestamp >= payment.dueDate;
    }
    
    function getOverduePayments(uint256 leaseId) external view returns (uint256[] memory) {
        uint256[] memory leasePaymentIds = _leasePayments[leaseId];
        uint256 overdueCount = 0;
        
        // Count overdue payments
        for (uint256 i = 0; i < leasePaymentIds.length; i++) {
            RentPayment memory payment = _rentPayments[leasePaymentIds[i]];
            if (!payment.isPaid && block.timestamp > payment.dueDate) {
                overdueCount++;
            }
        }
        
        // Build overdue payments array
        uint256[] memory overduePayments = new uint256[](overdueCount);
        uint256 index = 0;
        
        for (uint256 i = 0; i < leasePaymentIds.length; i++) {
            RentPayment memory payment = _rentPayments[leasePaymentIds[i]];
            if (!payment.isPaid && block.timestamp > payment.dueDate) {
                overduePayments[index] = leasePaymentIds[i];
                index++;
            }
        }
        
        return overduePayments;
    }
    
    // Emergency functions
    function emergencyWithdraw(
        address token,
        uint256 amount,
        address to
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(to != address(0), "Invalid recipient");
        IERC20(token).safeTransfer(to, amount);
    }
}

contracts/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title IdentityRegistry
 * @dev Simple identity registry for KYC/AML compliance
 */
contract IdentityRegistry is IIdentityRegistry, AccessControl, ReentrancyGuard {
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");
    bytes32 public constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");
    
    struct Identity {
        address identityContract;
        uint16 country;
        bool isVerified;
        bool exists;
        uint256 registrationTime;
    }
    
    mapping(address => Identity) private _identities;
    
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(REGISTRAR_ROLE, msg.sender);
        _grantRole(COMPLIANCE_ROLE, msg.sender);
    }
    
    function registerIdentity(
        address _user, 
        address _identity, 
        uint16 _country
    ) external override onlyRole(REGISTRAR_ROLE) {
        require(_user != address(0), "Invalid user address");
        require(_identity != address(0), "Invalid identity address");
        require(!_identities[_user].exists, "Identity already exists");
        
        _identities[_user] = Identity({
            identityContract: _identity,
            country: _country,
            isVerified: false,
            exists: true,
            registrationTime: block.timestamp
        });
        
        emit IdentityRegistered(_user, _identity, _country);
    }
    
    function verifyIdentity(address _user) external override onlyRole(COMPLIANCE_ROLE) {
        require(_identities[_user].exists, "Identity does not exist");
        
        _identities[_user].isVerified = true;
        emit IdentityVerified(_user, true);
    }
    
    function updateCountry(address _user, uint16 _country) external override onlyRole(COMPLIANCE_ROLE) {
        require(_identities[_user].exists, "Identity does not exist");
        
        _identities[_user].country = _country;
        emit CountryUpdated(_user, _country);
    }
    
    // View functions
    function identity(address _user) external view override returns (address) {
        return _identities[_user].identityContract;
    }
    
    function investorCountry(address _user) external view override returns (uint16) {
        return _identities[_user].country;
    }
    
    function isVerified(address _user) external view override returns (bool) {
        return _identities[_user].isVerified && _identities[_user].exists;
    }
    
    function contains(address _user) external view override returns (bool) {
        return _identities[_user].exists;
    }
    
    // Additional utility functions
    function getIdentityDetails(address _user) external view returns (
        address identityContract,
        uint16 country,
        bool verified,
        bool exists,
        uint256 registrationTime
    ) {
        Identity memory userIdentity = _identities[_user];
        return (
            userIdentity.identityContract,
            userIdentity.country,
            userIdentity.isVerified,
            userIdentity.exists,
            userIdentity.registrationTime
        );
    }
}

